	    public void AddTableQueries(Dictionary<string, Query> tenantQueries,Dictionary<string, QueryColumn> tenantQueryColumns, Dictionary<string, ObjectTable> objectTables, Dictionary<string, TextCode> textCodes, Repository<QueryGroup> queryGroupRepository, Repository<Query> queriesRepository, Repository<QueryColumn> queryColumnsRepository,Repository<TextCode> TextCodeRepository,Repository<Feature> FeaturesRepository, Dictionary<string, Feature> TenantFeatures,Repository<AdvancedQueryFilter> advancedQueryFiltersRepository,Dictionary<string, AdvancedQueryFilter> tenantAdvancedFilters,Dictionary<string, QueryGroup> tenantQueryGroups ,int contextTenant)
	    {  
	        
	        QueryGroup ReportQueryGroup = AddQueryGroups.AddQueryGroup(new QueryGroupPM() { Code = "RPRT", Name = "Report" }, queryGroupRepository,tenantQueryGroups);
						QueryGroup ReportQueryGroup1 = AddQueryGroups.AddQueryGroup(new QueryGroupPM() { Code = "d689", Name = " Query Group" }, queryGroupRepository,tenantQueryGroups);
				        queryGroupRepository.SubmitChanges();
	        ObjectTable ReportObjectTable = objectTables.ContainsKey("Report") ? objectTables["Report"] : null;
            if (ReportObjectTable == null)
            {
                IAmitalCloudContext objectContext = AmitalCloudContext.GetContext(contextTenant);  

                ReportObjectTable = objectContext.ObjectTables.Where(d => d.Name == "Report" && d.Tenant == 0).FirstOrDefault();
            }

	         
			List<Feature> addedFeatures = new List<Feature>();
			List<TextCode> addedTextCodes = new List<TextCode>();
			List<Query> addedQueries = new List<Query>();
			List<QueryColumn> addedQueryColumns = new List<QueryColumn>();
			List<AdvancedQueryFilter> addedQueryFilters = new List<AdvancedQueryFilter>();
   

			   TextCode ReportTextCode_0 = AddTextCodes.AddTextCode(new TextCodePM() { Code = "Report.Q.AllReports", DefaultText = @"All Reports",LocalDefaultText = null, ObjectTableId = ReportObjectTable.Id, Tenant = 0, TextCodeTypeCode = "Q", }, textCodes, addedTextCodes,contextTenant);
			   Feature ReportFeature_0 = AddRolesAndFeaturesClass.AddFeature(new FeaturePM() { Code = "ALLREPORTS", ObjectTableId = ReportObjectTable.Id, Tenant = 0, NameTextCodeCode = "ReportObjectTable.Features.AllReports", NameTextCodeDefaultText = "All Reports", FeatureTypeCode = "QUER", Packagable = true }, TenantFeatures, textCodes,ReportObjectTable, addedFeatures, addedTextCodes,contextTenant);

	        
																		    
	      

			  Query AllReportsQuery = AddQueries.AddQuery(new QueryPM() { NameTextCodeId = ReportTextCode_0.Id, NameTextCodeCode = ReportTextCode_0.Code, ObjectTableName = "Report", Code = "All Reports",  QueryGroupCode = "RPRT", IndexOrder = 0, Tenant = 0, ObjectTableId = ReportObjectTable.Id, QuerySection = "Report", SystemLevel = true, IsAddNewEntityEnabled = true, FeatureId = ReportFeature_0.Id,FeatureUniqeCode= ReportFeature_0.FeatureUniqeCode, DefaultSortColumn = null, DefaultSortDirection = null, Perspective = null }, addedQueries,contextTenant);
	
			 QueryColumn AllReportsQueryColumn_0 = AddQueries.AddQueryColumn(new QueryColumnPM { Tenant = 0, QueryId = AllReportsQuery.Id,QueryCode = AllReportsQuery.UniqueCode, IndexOrder = 0, ObjectFieldCode = "Report.Name" , ColumnWidth = 130 }, addedQueryColumns,contextTenant);

			 QueryColumn AllReportsQueryColumn_1 = AddQueries.AddQueryColumn(new QueryColumnPM { Tenant = 0, QueryId = AllReportsQuery.Id,QueryCode = AllReportsQuery.UniqueCode, IndexOrder = 1, ObjectFieldCode = "Report.Description" , ColumnWidth = 130 }, addedQueryColumns,contextTenant);

			 QueryColumn AllReportsQueryColumn_2 = AddQueries.AddQueryColumn(new QueryColumnPM { Tenant = 0, QueryId = AllReportsQuery.Id,QueryCode = AllReportsQuery.UniqueCode, IndexOrder = 2, ObjectFieldCode = "Report.FilterControlName" , ColumnWidth = 130 }, addedQueryColumns,contextTenant);
			SqlBulkInsert.BulkInsert("TextCodes", addedTextCodes,contextTenant);
			SqlBulkInsert.BulkInsert("Features", addedFeatures,contextTenant);
			SqlBulkInsert.BulkInsert("Queries", addedQueries,contextTenant);
			SqlBulkInsert.BulkInsert("QueryColumns", addedQueryColumns,contextTenant);
